INSERT INTO agent_tool_call(
  task_id, turn_id, call_id, tool_name, arguments_hash, arguments_json,
  status, attempt_no, duration_ms, started_at
) VALUES (
  #{taskId}, #{turnId}, #{callId}, #{toolName}, #{argumentsHash},
  #{arguments,typeHandler=com.zzy.finsight.infrastructure.persistence.mybatis.typehandler.ObjectJsonTypeHandler},
  'RUNNING', #{attemptNo}, 0, #{startedAt}
)

