UPDATE agent_turn
SET observation_summary = #{observationSummary}, status = #{status}, duration_ms = #{durationMs}
WHERE id = #{id}

UPDATE agent_tool_call
SET result_json = #{result,typeHandler=com.zzy.finsight.infrastructure.persistence.mybatis.typehandler.ObjectJsonTypeHandler},
    status = #{status}, duration_ms = #{durationMs}, error_code = #{errorCode},
    error_message = #{errorMessage}, completed_at = #{completedAt}
WHERE id = #{id}
